// Mounted check for async callbacks (replaces State.mounted).
bool isMounted() => context.mounted;

void setSeekPreview(Duration target, Duration duration, double fraction) {
  if (!isLinux) return;
  seekPreviewClearTimer.value?.cancel();
  seekPreview.value = _SeekPreview(
    targetMs: target.inMilliseconds,
    durationMs: duration.inMilliseconds,
    fraction: fraction,
  );
}

void clearSeekPreview() {
  if (!isLinux) return;
  seekPreviewClearTimer.value?.cancel();
  // Keep it visible for a brief moment after the drag so automated
  // screenshot capture can reliably observe both during-gesture and
  // post-gesture states.
  seekPreviewClearTimer.value = Timer(const Duration(milliseconds: 120), () {
    if (isMounted()) seekPreview.value = null;
  });
}

